-- ====================================================================
-- MALYPETSHOP - ESQUEMA Y DATOS COMPLETOS PARA SUPABASE (POSTGRESQL)
-- ====================================================================

-- 1. CREACIÓN DE TABLAS
DROP TABLE IF EXISTS product_variants CASCADE;
DROP TABLE IF EXISTS products CASCADE;
DROP TABLE IF EXISTS brands CASCADE;
DROP TABLE IF EXISTS categories CASCADE;
DROP TABLE IF EXISTS store_settings CASCADE;
DROP TABLE IF EXISTS site_visits CASCADE;
DROP TABLE IF EXISTS orders CASCADE;

CREATE TABLE categories (
    id SERIAL PRIMARY KEY,
    slug TEXT UNIQUE NOT NULL,
    name TEXT NOT NULL,
    pet_type TEXT,
    icon TEXT,
    display_order INT DEFAULT 0
);

CREATE TABLE brands (
    id SERIAL PRIMARY KEY,
    name TEXT UNIQUE NOT NULL,
    tier TEXT,
    origin TEXT
);

CREATE TABLE products (
    id INT PRIMARY KEY,
    category_id INT REFERENCES categories(id) ON DELETE SET NULL,
    brand_id INT REFERENCES brands(id) ON DELETE SET NULL,
    name TEXT NOT NULL,
    slug TEXT NOT NULL,
    description TEXT,
    pet_type TEXT,
    subcat TEXT,
    breed_size TEXT,
    badge TEXT,
    image_url TEXT,
    is_featured BOOLEAN DEFAULT FALSE,
    is_promo BOOLEAN DEFAULT FALSE,
    promo_tag TEXT,
    active BOOLEAN DEFAULT TRUE,
    created_at TIMESTAMPTZ DEFAULT NOW()
);

CREATE TABLE product_variants (
    id SERIAL PRIMARY KEY,
    product_id INT REFERENCES products(id) ON DELETE CASCADE,
    presentation_name TEXT NOT NULL,
    weight_kg NUMERIC,
    cost_price NUMERIC NOT NULL,
    margin_percent NUMERIC NOT NULL,
    sale_price NUMERIC NOT NULL,
    list_price NUMERIC NOT NULL,
    stock_qty INT DEFAULT 100,
    sku TEXT,
    is_default BOOLEAN DEFAULT FALSE
);

CREATE TABLE store_settings (
    key TEXT PRIMARY KEY,
    value TEXT NOT NULL,
    description TEXT
);

CREATE TABLE site_visits (
    id BIGSERIAL PRIMARY KEY,
    visit_date DATE DEFAULT CURRENT_DATE,
    visit_time TIMESTAMPTZ DEFAULT NOW(),
    session_id TEXT,
    user_agent TEXT
);

CREATE TABLE orders (
    id BIGSERIAL PRIMARY KEY,
    order_code TEXT UNIQUE NOT NULL,
    customer_name TEXT,
    customer_phone TEXT,
    customer_address TEXT,
    payment_method TEXT,
    subtotal NUMERIC,
    total NUMERIC,
    status TEXT DEFAULT 'pendiente',
    notes TEXT,
    created_at TIMESTAMPTZ DEFAULT NOW()
);


-- 2. INSERTAR CATEGORÍAS
SELECT setval('categories_id_seq', (SELECT MAX(id) FROM categories));

-- 3. INSERTAR MARCAS
SELECT setval('brands_id_seq', (SELECT MAX(id) FROM brands));

-- 4. INSERTAR PRODUCTOS (144 PRODUCTOS)

-- 5. INSERTAR VARIANTES DE PRODUCTOS (PRESENTACIONES Y PRECIOS)
SELECT setval('product_variants_id_seq', (SELECT MAX(id) FROM product_variants));

-- 6. INSERTAR AJUSTES DE LA TIENDA

-- 7. SEGURIDAD Y PERMISOS PÚBLICOS (ROW LEVEL SECURITY)
ALTER TABLE categories ENABLE ROW LEVEL SECURITY;
ALTER TABLE brands ENABLE ROW LEVEL SECURITY;
ALTER TABLE products ENABLE ROW LEVEL SECURITY;
ALTER TABLE product_variants ENABLE ROW LEVEL SECURITY;
ALTER TABLE store_settings ENABLE ROW LEVEL SECURITY;
ALTER TABLE site_visits ENABLE ROW LEVEL SECURITY;
ALTER TABLE orders ENABLE ROW LEVEL SECURITY;

-- Políticas de lectura pública (cualquier cliente puede ver catálogo)
CREATE POLICY "Public Read Categories" ON categories FOR SELECT USING (true);
CREATE POLICY "Public Read Brands" ON brands FOR SELECT USING (true);
CREATE POLICY "Public Read Products" ON products FOR SELECT USING (true);
CREATE POLICY "Public Read Variants" ON product_variants FOR SELECT USING (true);
CREATE POLICY "Public Read Settings" ON store_settings FOR SELECT USING (true);

-- Políticas de administración (edición de productos y ajustes desde la web)
CREATE POLICY "Public Manage Products" ON products FOR ALL USING (true) WITH CHECK (true);
CREATE POLICY "Public Manage Variants" ON product_variants FOR ALL USING (true) WITH CHECK (true);
CREATE POLICY "Public Manage Settings" ON store_settings FOR ALL USING (true) WITH CHECK (true);
CREATE POLICY "Public Insert Visits" ON site_visits FOR INSERT WITH CHECK (true);
CREATE POLICY "Public Read Visits" ON site_visits FOR SELECT USING (true);
CREATE POLICY "Public Insert Orders" ON orders FOR INSERT WITH CHECK (true);
CREATE POLICY "Public Read Orders" ON orders FOR SELECT USING (true);
